// Golden tests against SmolLM2-135M's reference tokenizer (Hugging Face
// tokenizers). The fixtures in tests/fixtures/smollm2/ are generated by
// tools/make_tokenizer_fixtures.py; the ids must match exactly.

#include <bit>
#include <chrono>
#include <cstddef>
#include <cstdint>
#include <filesystem>
#include <iostream>
#include <span>
#include <string>
#include <vector>

#include "harness/test.hpp"
#include "io/checksum.hpp"
#include "io/file.hpp"
#include "io/json.hpp"
#include "tokenizer/bpe_tokenizer.hpp"

namespace {

using titan::io::JsonValue;
using titan::tokenizer::BpeTokenizer;

const std::filesystem::path kFixtures =
    std::filesystem::path(TITAN_FIXTURES_DIR) / "smollm2";

// The fixture "!\x04!": byte 0x04 has no symbol in SmolLM2's vocabulary, so
// it is dropped and the reference decodes the ids to "!!", not the text.
constexpr std::size_t kDroppedByteCase = 24;
constexpr std::size_t kNumCases = 25;

JsonValue read_fixture(const char* name) {
    return titan::io::parse_json(titan::io::read_file(kFixtures / name));
}

// Parsing the 2 MB tokenizer.json once keeps the suite fast.
const BpeTokenizer& reference() {
    static const BpeTokenizer tokenizer =
        BpeTokenizer::from_json(read_fixture("tokenizer.json"));
    return tokenizer;
}

struct Case {
    std::string text;
    std::vector<std::int32_t> ids;
    std::string decoded;
};

const std::vector<Case>& cases() {
    static const std::vector<Case> all = [] {
        std::vector<Case> out;
        const JsonValue doc = read_fixture("encode.json");
        for (const JsonValue& c : doc.at("cases").as_array()) {
            Case item{
                c.at("text").as_string(), {}, c.at("decoded").as_string()};
            for (const JsonValue& id : c.at("ids").as_array()) {
                item.ids.push_back(static_cast<std::int32_t>(id.as_int()));
            }
            out.push_back(std::move(item));
        }
        return out;
    }();
    return all;
}

// Reports the case index and the first position where the ids differ.
void expect_ids(std::size_t index, const std::vector<std::int32_t>& got,
                const std::vector<std::int32_t>& want) {
    if (got == want) {
        return;
    }
    std::size_t pos = 0;
    while (pos < got.size() && pos < want.size() && got[pos] == want[pos]) {
        ++pos;
    }
    const auto at = [pos](const std::vector<std::int32_t>& ids) {
        return pos < ids.size() ? std::to_string(ids[pos]) : "<end>";
    };
    titan::test::report_failure(
        __FILE__, __LINE__,
        "case " + std::to_string(index) + ": ids differ at position " +
            std::to_string(pos) + " (" + at(got) + " vs " + at(want) +
            "; lengths " + std::to_string(got.size()) + " vs " +
            std::to_string(want.size()) + ")");
}

void expect_encode_matches(const BpeTokenizer& tokenizer) {
    const std::vector<Case>& all = cases();
    TITAN_EXPECT_EQ(all.size(), kNumCases);
    for (std::size_t i = 0; i < all.size(); ++i) {
        expect_ids(i, tokenizer.encode(all[i].text), all[i].ids);
    }
}

}  // namespace

TITAN_TEST(SmolLM2, LoadsReference) {
    const BpeTokenizer& tokenizer = reference();
    TITAN_EXPECT_EQ(tokenizer.vocab_size(), 49152);
    TITAN_EXPECT_EQ(tokenizer.num_merges(), 48900);
    TITAN_EXPECT(tokenizer.eos_id() == 0);
}

TITAN_TEST(SmolLM2, EncodeMatchesReference) {
    expect_encode_matches(reference());
}

TITAN_TEST(SmolLM2, DecodeMatchesReference) {
    const std::vector<Case>& all = cases();
    TITAN_EXPECT_EQ(all.size(), kNumCases);
    for (std::size_t i = 0; i < all.size(); ++i) {
        const std::string decoded = reference().decode(all[i].ids);
        TITAN_EXPECT_EQ(decoded, all[i].decoded);
        if (i == kDroppedByteCase) {
            TITAN_EXPECT_EQ(decoded, std::string("!!"));
        } else {
            TITAN_EXPECT_EQ(decoded, all[i].text);
        }
    }
}

TITAN_TEST(SmolLM2, CorpusMatchesReference) {
    const std::filesystem::path meta_path = kFixtures / "corpus.json";
    if (!std::filesystem::exists(meta_path)) {
        TITAN_SKIP("no tests/fixtures/smollm2/corpus.json");
    }
    const JsonValue meta = read_fixture("corpus.json");
    const std::filesystem::path corpus_path =
        std::filesystem::path(TITAN_SOURCE_DIR) / meta.at("path").as_string();
    if (!std::filesystem::exists(corpus_path)) {
        TITAN_SKIP("no " + meta.at("path").as_string());
    }
    const std::string corpus = titan::io::read_file(corpus_path);
    TITAN_EXPECT_EQ(static_cast<std::int64_t>(corpus.size()),
                    meta.at("bytes").as_int());

    const auto start = std::chrono::steady_clock::now();
    const std::vector<std::int32_t> ids = reference().encode(corpus);
    const std::chrono::duration<double> elapsed =
        std::chrono::steady_clock::now() - start;
    std::cout << "SmolLM2.CorpusMatchesReference: encoded " << corpus.size()
              << " bytes in " << elapsed.count() << " s\n";

    TITAN_EXPECT_EQ(static_cast<std::int64_t>(ids.size()),
                    meta.at("tokens").as_int());
    // The reference CRC is zlib.crc32 over the ids as little-endian int32.
    static_assert(std::endian::native == std::endian::little);
    const std::uint32_t crc =
        titan::io::crc32(std::as_bytes(std::span<const std::int32_t>(ids)));
    TITAN_EXPECT_EQ(static_cast<std::int64_t>(crc), meta.at("crc32").as_int());
}

TITAN_TEST(SmolLM2, JsonRoundTrip) {
    const BpeTokenizer copy = BpeTokenizer::from_json(reference().to_json());
    TITAN_EXPECT_EQ(copy.vocab_size(), reference().vocab_size());
    TITAN_EXPECT_EQ(copy.num_merges(), reference().num_merges());
    expect_encode_matches(copy);
}
